export const examHistoryKey='mecanica.exam-history.v1';
export function validFinished(e){return e&&typeof e.id==='string'&&e.status==='finished'&&typeof e.finishedAt==='string'&&Number.isFinite(+new Date(e.finishedAt))&&Array.isArray(e.questions)&&e.questions.length===6&&Array.isArray(e.answers)&&e.answers.length===6&&e.questions.every((q,i)=>['pressure','jam','sensor','pressureWave','combined'].includes(q.kind)&&Number.isInteger(q.index)&&q.index>0&&q.index<=1500&&q.answer&&typeof q.answer.id==='string'&&typeof q.answer.label==='string'&&Array.isArray(q.options)&&q.options.some(o=>o.id===e.answers[i])&&Array.isArray(q.changes));}
export function createExamHistory(storage){let list=[],warning='';try{const raw=JSON.parse(storage.getItem(examHistoryKey)||'[]');if(!Array.isArray(raw))throw Error();list=raw.filter(validFinished).slice(-50);}catch{warning='No se pudo leer el historial de exámenes. Los nuevos exámenes se conservarán en esta sesión.';}return {all:()=>structuredClone(list),warning:()=>warning,add(exam){if(!validFinished(exam)||list.some(e=>e.id===exam.id))return;list.push(structuredClone(exam));list=list.slice(-50);if(warning)return;try{storage.setItem(examHistoryKey,JSON.stringify(list));}catch{warning='No se pudo guardar el historial de exámenes; disponible solo durante esta sesión.';}}};}
export function examScore(e){return Math.round(e.answers.filter((a,i)=>a===e.questions[i].answer.id).length/6*100);}
export function examMastery(exams){const map=new Map();for(const e of [...exams].sort((a,b)=>a.finishedAt.localeCompare(b.finishedAt)))for(const [i,q]of e.questions.entries()){if(!map.has(q.answer.id))map.set(q.answer.id,{signal:q.answer.id,label:q.answer.label,results:[],examIds:new Set()});map.get(q.answer.id).examIds.add(e.id);map.get(q.answer.id).results.push(e.answers[i]===q.answer.id);}return [...map.values()].map(s=>{const recent=s.results.slice(-5),correct=recent.filter(Boolean).length;return {...s,correct,n:recent.length,errors:s.results.filter(v=>!v).length,status:recent.length<3||s.examIds.size<3?'Datos insuficientes':correct===recent.length?'Aciertos consistentes':correct/recent.length>=.6?'En progreso':'Prioridad de repaso'};});}
